package br.com.luvi.financaspessoais.grupo.entity;
import br.com.luvi.financaspessoais.grupo.enums.PerfilGrupo; import br.com.luvi.financaspessoais.usuario.entity.Usuario; import jakarta.persistence.*;
@Entity @Table(name="grupo_membros",uniqueConstraints=@UniqueConstraint(name="uk_grupo_usuario",columnNames={"grupo_id","usuario_id"})) public class GrupoMembro { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Grupo grupo; @ManyToOne(optional=false) private Usuario usuario; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PerfilGrupo perfil; public Long getId(){return id;} public Grupo getGrupo(){return grupo;} public void setGrupo(Grupo v){grupo=v;} public Usuario getUsuario(){return usuario;} public void setUsuario(Usuario v){usuario=v;} public PerfilGrupo getPerfil(){return perfil;} public void setPerfil(PerfilGrupo v){perfil=v;} }